const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const nEl = document.getElementById('n');
const fEl = document.getElementById('f');
const DPR = Math.min(window.devicePixelRatio||1,2);

let particles = [];
let mouse = {x:-9999,y:-9999,active:false};
const COUNT = 140;
const LINK_DIST = 120;

function resize(){
  const r = canvas.getBoundingClientRect();
  canvas.width = Math.max(1, Math.floor(r.width * DPR));
  canvas.height = Math.max(1, Math.floor(r.height * DPR));
  canvas.style.width = r.width+'px';
  canvas.style.height = r.height+'px';
}
const ro = new ResizeObserver(resize); ro.observe(canvas);
resize();

function rand(a,b){return a+Math.random()*(b-a);}
function makeParticle(w,h){
  return {
    x: rand(0,w), y: rand(0,h),
    vx: rand(-0.4,0.4), vy: rand(-0.4,0.4),
    r: rand(1.2,2.6),
    hue: rand(200,290),
    life: rand(0,1)
  };
}

function init(){
  particles = [];
  const w = canvas.width/DPR, h = canvas.height/DPR;
  for(let i=0;i<COUNT;i++) particles.push(makeParticle(w,h));
}
init();

canvas.addEventListener('mousemove', e=>{
  const r = canvas.getBoundingClientRect();
  mouse.x = (e.clientX - r.left); mouse.y = (e.clientY - r.top); mouse.active=true;
});
canvas.addEventListener('mouseleave', ()=>{ mouse.active=false; });

document.getElementById('add').onclick = ()=>{
  const w=canvas.width/DPR, h=canvas.height/DPR;
  for(let i=0;i<40;i++) particles.push(makeParticle(w,h));
};
document.getElementById('reset').onclick = init;

let last = performance.now(), fps=60, frameCount=0, fpsTimer=performance.now();
function loop(now){
  const dt = Math.min((now-last)/16.67, 3); last=now;
  const w = canvas.width/DPR, h = canvas.height/DPR;
  ctx.setTransform(DPR,0,0,DPR,0,0);
  ctx.clearRect(0,0,w,h);

  // subtle vignette
  const g = ctx.createRadialGradient(w/2,h/2,Math.min(w,h)*0.2,w/2,h/2,Math.max(w,h)*0.7);
  g.addColorStop(0,'rgba(0,0,0,0)');
  g.addColorStop(1,'rgba(0,0,0,0.35)');
  ctx.fillStyle = g; ctx.fillRect(0,0,w,h);

  // update
  for(const p of particles){
    p.life += 0.003*dt;
    p.x += p.vx*dt; p.y += p.vy*dt;
    if(p.x<0){p.x=0;p.vx*=-1;} if(p.x>w){p.x=w;p.vx*=-1;}
    if(p.y<0){p.y=0;p.vy*=-1;} if(p.y>h){p.y=h;p.vy*=-1;}
    if(mouse.active){
      const dx = mouse.x - p.x, dy = mouse.y - p.y;
      const d = Math.hypot(dx,dy);
      if(d < 140 && d>0){
        const f = (140-d)/140*0.04;
        p.vx += dx/d*f; p.vy += dy/d*f;
      }
    }
    // damping
    p.vx*=0.995; p.vy*=0.995;
    const spd = Math.hypot(p.vx,p.vy);
    if(spd>1.6){p.vx/=spd*0.625;p.vy/=spd*0.625;}
